sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
   // console.log(event.payload.appliedFilters[0].values.toString());
    //api.setState('projectFilter',event.payload.appliedFilters[0].values.toString());
    //api.data.list_controller.refresh();
    var arr = [];
    // Replace 'look_up_records_1' with the exact name of your Look up records data resource
    var results = api.data.project_data_source.results;
    console.log(results);
    for (var i = 0; i < results.length; i++) {
        arr.push(results[i]._row_data.uniqueValue);
    }
    console.log(arr.toString());
    console.log("payload "+ event.payload.value )
    if (event.payload.value.toString() == '') {

         console.log("I am in if");
        api.setState('projectFilter', arr.toString());
        api.data.list_controller.refresh();
    } else {

        console.log("I am in else");
        api.setState('projectFilter', event.payload.value.toString());
        api.data.list_controller.refresh();
    }

}
